    {
      id: 'football',
      short: 'Football',
      title: 'Football Matchday Screener',
      description: 'Half-time and full-time profile analysis. Correct score clusters, BTTS, 5-lamp scoreboards, and live market ranking.',
      accent: '#22c55e',
      path: '/football',
      category: 'real'
    },
    {
      id: 'basketball',
      short: 'Basketball',
      title: 'Basketball Matchday Screener',
